CREATE TABLE IF NOT EXISTS erp_lock (id INTEGER PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS usuarios (id INTEGER PRIMARY KEY AUTO_INCREMENT, nombre VARCHAR(100) NOT NULL, correo VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, rol VARCHAR(30) NOT NULL, estado VARCHAR(15) NOT NULL DEFAULT 'activo', session_version INTEGER NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS insumos (id INTEGER PRIMARY KEY AUTO_INCREMENT, nombre VARCHAR(120) NOT NULL UNIQUE, categoria VARCHAR(80) NOT NULL, unidad VARCHAR(20) NOT NULL, stock_miles BIGINT NOT NULL DEFAULT 0, reservado_miles BIGINT NOT NULL DEFAULT 0, minimo_miles BIGINT NOT NULL, costo_centavos BIGINT NOT NULL, activo INTEGER NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS productos (id INTEGER PRIMARY KEY AUTO_INCREMENT, nombre VARCHAR(120) NOT NULL UNIQUE, categoria VARCHAR(80) NOT NULL, precio_centavos BIGINT NOT NULL, activo INTEGER NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS recetas (producto_id INTEGER NOT NULL, insumo_id INTEGER NOT NULL, cantidad_miles BIGINT NOT NULL, PRIMARY KEY(producto_id,insumo_id), FOREIGN KEY(producto_id) REFERENCES productos(id), FOREIGN KEY(insumo_id) REFERENCES insumos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS proveedores (id INTEGER PRIMARY KEY AUTO_INCREMENT, nombre VARCHAR(120) NOT NULL UNIQUE, contacto VARCHAR(150) NOT NULL, categoria VARCHAR(80) NOT NULL, activo INTEGER NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ordenes_compra (id INTEGER PRIMARY KEY AUTO_INCREMENT, proveedor_id INTEGER NOT NULL, fecha VARCHAR(30) NOT NULL, estado VARCHAR(20) NOT NULL DEFAULT 'Pendiente', total_centavos BIGINT NOT NULL, usuario_id INTEGER NOT NULL, FOREIGN KEY(proveedor_id) REFERENCES proveedores(id), FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS compra_items (id INTEGER PRIMARY KEY AUTO_INCREMENT, orden_id INTEGER NOT NULL, insumo_id INTEGER NOT NULL, cantidad_miles BIGINT NOT NULL, costo_centavos BIGINT NOT NULL, FOREIGN KEY(orden_id) REFERENCES ordenes_compra(id), FOREIGN KEY(insumo_id) REFERENCES insumos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS facturas (id INTEGER PRIMARY KEY AUTO_INCREMENT, folio VARCHAR(70) NOT NULL UNIQUE, cliente VARCHAR(100) NOT NULL, fecha VARCHAR(30) NOT NULL, total_centavos BIGINT NOT NULL, metodo VARCHAR(30) NOT NULL, usuario_id INTEGER NOT NULL, request_key VARCHAR(100) NOT NULL UNIQUE, FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS factura_items (id INTEGER PRIMARY KEY AUTO_INCREMENT, factura_id INTEGER NOT NULL, producto_id INTEGER NOT NULL, nombre VARCHAR(120) NOT NULL, cantidad INTEGER NOT NULL, precio_centavos BIGINT NOT NULL, FOREIGN KEY(factura_id) REFERENCES facturas(id), FOREIGN KEY(producto_id) REFERENCES productos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS movimientos (id INTEGER PRIMARY KEY AUTO_INCREMENT, fecha VARCHAR(30) NOT NULL, concepto VARCHAR(180) NOT NULL, categoria VARCHAR(60) NOT NULL, tipo VARCHAR(15) NOT NULL, monto_centavos BIGINT NOT NULL, referencia VARCHAR(100) UNIQUE, usuario_id INTEGER NOT NULL, FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS inventario_movimientos (id INTEGER PRIMARY KEY AUTO_INCREMENT, insumo_id INTEGER NOT NULL, fecha VARCHAR(30) NOT NULL, cantidad_miles BIGINT NOT NULL, motivo VARCHAR(180) NOT NULL, usuario_id INTEGER NOT NULL, FOREIGN KEY(insumo_id) REFERENCES insumos(id), FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS empleados (id INTEGER PRIMARY KEY AUTO_INCREMENT, nombre VARCHAR(100) NOT NULL, puesto VARCHAR(80) NOT NULL, turno VARCHAR(100) NOT NULL, estado VARCHAR(20) NOT NULL, salario_centavos BIGINT NOT NULL, correo VARCHAR(150) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS nominas (id INTEGER PRIMARY KEY AUTO_INCREMENT, empleado_id INTEGER NOT NULL, periodo VARCHAR(7) NOT NULL, monto_centavos BIGINT NOT NULL, fecha VARCHAR(30) NOT NULL, usuario_id INTEGER NOT NULL, UNIQUE(empleado_id,periodo), FOREIGN KEY(empleado_id) REFERENCES empleados(id), FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS paypal_ordenes (id VARCHAR(50) PRIMARY KEY, usuario_id INTEGER NOT NULL, estado VARCHAR(30) NOT NULL, total_centavos BIGINT NOT NULL, moneda VARCHAR(3) NOT NULL, snapshot TEXT NOT NULL, factura_id INTEGER, capture_id VARCHAR(100) UNIQUE, fecha VARCHAR(30) NOT NULL, FOREIGN KEY(usuario_id) REFERENCES usuarios(id), FOREIGN KEY(factura_id) REFERENCES facturas(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS correo_envios (id INTEGER PRIMARY KEY AUTO_INCREMENT, factura_id INTEGER NOT NULL, usuario_id INTEGER NOT NULL, destinatario VARCHAR(150) NOT NULL, estado VARCHAR(20) NOT NULL, message_id VARCHAR(200), error VARCHAR(300), request_key VARCHAR(100) NOT NULL UNIQUE, fecha VARCHAR(30) NOT NULL, FOREIGN KEY(factura_id) REFERENCES facturas(id), FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
